package dev.pathland.view.emit;

import dev.pathland.view.Categories;
import dev.pathland.view.Color;
import dev.pathland.view.Commands;
import dev.pathland.view.ValueTypes;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * An {@link OpcodeSink} that accumulates a self-contained {@link ProtocolFrame} (opcodes +
 * string section) entirely in the JVM. This is the SSR / WebSocket path: the frame is
 * rendered to HTML or encoded to the network batch wire format.
 */
public class FrameOpcodeSink implements OpcodeSink {

    private final List<Opcode> opcodes = new ArrayList<>();
    private final ByteArrayOutputStream strings = new ByteArrayOutputStream();
    private ProtocolFrame frame = ProtocolFrame.EMPTY;
    private int framesProduced;

    /** The frame built by the last {@code beginFrame/endFrame} pair. */
    public ProtocolFrame frame() {
        return frame;
    }

    /** Number of completed frames so far (unchanged signals do not produce a frame). */
    public int framesProduced() {
        return framesProduced;
    }

    public boolean hasChanges() {
        return !opcodes.isEmpty();
    }

    @Override
    public void beginFrame() {
        opcodes.clear();
        strings.reset();
    }

    @Override
    public void endFrame() {
        frame = new ProtocolFrame(List.copyOf(opcodes), strings.toByteArray());
        framesProduced++;
    }

    @Override
    public void createNode(int id, int component) {
        push(Categories.TREE, Commands.Tree.CREATE_NODE, 0, id, component, 0);
    }

    @Override
    public void deleteNode(int id) {
        push(Categories.TREE, Commands.Tree.DELETE_NODE, 0, id, 0, 0);
    }

    @Override
    public void insertChild(int parent, int child, int index) {
        push(Categories.TREE, Commands.Tree.INSERT_CHILD, 0, parent, child, index);
    }

    @Override
    public void removeChild(int parent, int child) {
        push(Categories.TREE, Commands.Tree.REMOVE_CHILD, 0, parent, child, 0);
    }

    @Override
    public void moveChild(int parent, int child, int newIndex) {
        push(Categories.TREE, Commands.Tree.MOVE_CHILD, 0, parent, child, newIndex);
    }

    @Override
    public void setText(int nodeId, String text) {
        int offset = strings.size();
        writeString(text);
        push(Categories.PARAMETER, Commands.Parameter.SET_TEXT, 0, nodeId, offset, 0);
    }

    @Override
    public void setProperty(int nodeId, int property, int valueType, Object value) {
        int b = (valueType << 16) | (property & 0xFFFF);
        if (valueType == ValueTypes.STRING) {
            int offset = strings.size();
            writeString((String) value);
            push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, offset);
        } else if (valueType == ValueTypes.DESIGN_TOKEN) {
            // C = arena offset of the token path (spec/TOKENS.md).
            int offset = strings.size();
            writeString(((Color) value).token());
            push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, offset);
        } else if (valueType == ValueTypes.LIST) {
            // C = arena offset of a length-prefixed array `[u32 count][f32 × count]`
            // (spec/OPCODE.md §Value types — a `FIT_QUERY` threshold table).
            int offset = strings.size();
            float[] elements = (float[]) value;
            writeIntLE(elements.length);
            for (float element : elements) {
                strings.write(Float.floatToIntBits(element) & 0xFF);
                strings.write((Float.floatToIntBits(element) >>> 8) & 0xFF);
                strings.write((Float.floatToIntBits(element) >>> 16) & 0xFF);
                strings.write((Float.floatToIntBits(element) >>> 24) & 0xFF);
            }
            push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, offset);
        } else {
            push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, ValueEncoder.encodeBits(valueType, value));
        }
    }

    @Override
    public void setDate(int nodeId, int days, int millisOfDay) {
        push(Categories.PARAMETER, Commands.Parameter.SET_DATE, 0, nodeId, days, millisOfDay);
    }

    @Override
    public void setDesignToken(String path, int valueType, Object value) {
        int pathOffset = strings.size();
        writeString(path);
        int c;
        if (valueType == ValueTypes.STRING) {
            c = strings.size();
            writeString((String) value);
        } else {
            c = ValueEncoder.encodeBits(valueType, value);
        }
        push(Categories.PARAMETER, Commands.Parameter.SET_DESIGN_TOKEN, 0, pathOffset, valueType, c);
    }

    /** Append a length-prefixed string to the string section, returning its offset. */
    public int writeString(String text) {
        int offset = strings.size();
        byte[] utf8 = text.getBytes(StandardCharsets.UTF_8);
        writeIntLE(utf8.length);
        strings.writeBytes(utf8);
        return offset;
    }

    private void push(int category, int command, int flags, int a, int b, int c) {
        opcodes.add(new Opcode(category, command, flags, a, b, c));
    }

    private void writeIntLE(int value) {
        strings.write(value & 0xFF);
        strings.write((value >>> 8) & 0xFF);
        strings.write((value >>> 16) & 0xFF);
        strings.write((value >>> 24) & 0xFF);
    }
}

package dev.pathland.view;

import dev.pathland.view.emit.PathlandNode;

/**
 * A composable view. Composite views declare their subtree with
 * {@link #body()}; the library's primitives (leaves, stacks, controls) instead override
 * {@link #render(Environment)} to materialize a {@link PathlandNode}. The interface is
 * open: the library ships the leaf primitives and modifier wrappers, and application
 * code (Quarkus, Spring Boot, desktop) defines its own views by implementing
 * {@code View} directly.
 *
 * <p>{@link #body()} is evaluated once at mount — reactivity comes from signals
 * ({@code Text.make(t -> t.text(Signal))}, {@code Signals.computed}), not from body
 * re-evaluation.
 *
 * <p>Modifiers are {@link ViewModifier} values applied with {@link #modifiers(ViewModifier...)}
 * — built-in and application-authored modifiers share one mechanism (spec DSL.md
 * §5.6), applied innermost-first. There is no per-modifier factory sugar on this
 * interface. Constructor (structural/layout) properties are passed to the view
 * constructors and are never chainable.
 */
public interface View {

    /**
     * The base marker for a view's **value config** ({@code V.Config}). The
     * config is populated by the static {@code View.make(Consumer<Config>)}
     * factory and is the same type a style's {@code makeBody(Config)} reads
     * (spec DSL.md §5.7).
     */
    interface Config {
    }

    /**
     * Declarative composition: a composite view returns its subtree here. Primitives
     * return {@code this} (the identity body) and instead override
     * {@link #render(Environment)}.
     */
    default View body() {
        return this;
    }

    /**
     * Materialize this view into retained node(s). Composite views resolve
     * {@link #body()} first (recursively); primitives override this to build a
     * {@link PathlandNode}.
     */
    default PathlandNode render(Environment env) {
        dev.pathland.view.state.PersistentState state = env.state();
        if (state != null) {
            state.connect(this); // wire this view's State fields (idempotent)
        }
        View resolved = body();
        if (resolved != this) {
            return resolved.render(env);
        }
        throw new UnsupportedOperationException(
                getClass().getName() + " must override body() (composite) or render() (primitive)");
    }

    /**
     * Wrap this view in one or more modifiers ({@code .modifier}), applied
     * innermost-first: {@code modifiers(A, B, C)} ≡ {@code modifiers(A).modifiers(B).modifiers(C)}.
     * A single modifier is the common case; an empty call returns {@code this}.
     * {@code with(...)} is for values only — modifiers always go through this
     * {@code modifiers(...)} operation.
     */
    default View modifiers(ViewModifier... modifiers) {
        View result = this;
        for (ViewModifier modifier : modifiers) {
            result = Modified.apply(result, modifier);
        }
        return result;
    }
}

