                    fresh.id = nextId++;
                    int id = fresh.id, component = fresh.component, index = i;
                    ops.add(() -> sink.createNode(id, component));
                    emitSubtreeInto(ops, fresh);
                    int parentId = parent.id;
                    ops.add(() -> sink.insertChild(parentId, id, index));
                }
            }
        }
