+        public Config duration(float seconds) {
+            this.duration = seconds;
+            return this;
+        }
+
+        /** Advance (e.g. to the next track) when the media ends ({@code MEDIA_ENDED}). */
+        public Config onEnded(Runnable onEnded) {
