+                        sink.set(seconds);
+                    }
+                }
+
+                @Override
+                public void onEnded() {
+                    if (config.onEnded != null) {
+                        config.onEnded.run();
+                    }
+                }
+
+                @Override
+                public void onVolumeChanged(float value) {
+                    WritableSignal<Float> sink =
+                            config.reportVolume != null ? config.reportVolume : config.volume;
+                    if (sink != null) {
+                        sink.set(value);
+                    }
+                }
+            };
