 pub trait Configurable: View + Sized {
     /// This view's config type.
     type Config: Default;
     /// The current config.
     fn config(&self) -> &Self::Config;
     /// The mutable config (the `with` closure receives this).
     fn config_mut(&mut self) -> &mut Self::Config;

