 /** A shell's role behavior (see `pathland-render-html::role_spec`).
  *  Generic `div`/`span` shells may be retagged; native controls convey
  *  their own role; anything else only gets an ARIA attribute. */
 export type ShellKind = "generic" | "native" | "other";

 /** The semantic tag a `(shell kind, role)` pair resolves to, or null. */
 export function semanticTag(kind: ShellKind, role: number): string | null {
   if (kind !== "generic") return null;
   const found = ROLE_TAGS.find((r) => r.role === role);
   return found ? found.tag : null;
 }

